// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · Sözel mantık ve akıl yürütme (sıralama, eşleştirme, koşullu çıkarım; her soru kendi verisini içerir) (kolay).
const ozExam4Kolay = <(String, String, List<String>, String)>[
  ('Dört arkadaştan Tuna, Mert\'ten kısa ama Sena\'dan uzundur. Duru ise grubun en uzunu değildir ve Sena\'dan kısadır. Uzundan kısaya sıralandığında ikinci sırada kim yer alır?', 'Tuna', ['Mert', 'Sena', 'Duru'], 'Bilgilerden Mert > Tuna > Sena > Duru sıralaması çıkar. İkinci sırada Tuna vardır.'),
  ('Bir toplantıya Ayşe, Ozan\'dan önce; Ozan da Pelin\'den önce gelmiştir. Umut ise Ayşe\'den sonra gelmiştir. Dördü farklı zamanlarda geldiğine göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'Ayşe ilk gelen kişidir.', ['Umut en son gelen kişidir.', 'Pelin en son gelmiştir.', 'Ozan ikinci gelmiştir.'], 'Ayşe; Ozan, Pelin ve Umut\'un hepsinden önce geldiği için ilktir. Umut\'un yeri kesin olmadığından diğer seçenekler yalnızca olasıdır.'),
  ('Kare bir masanın her kenarına bir kişi oturmuştur. Ali\'nin karşısında Oya, sağında Can oturmaktadır. Dördüncü kişi Ece\'dir. Ece kimin karşısındadır?', 'Can', ['Ali', 'Oya', 'Ece\'nin karşısı boştur'], 'Ece, Ali\'nin solundaki yerde kalır. Ali\'nin solunun karşısı Ali\'nin sağıdır; orada da Can oturur.'),
  ('Ali, Ece ve Nur\'un meslekleri doktor, mimar ve pilottur; her birinin mesleği farklıdır. Ali pilot değildir. Ece ne doktordur ne de mimardır. Nur mimar değildir. Ali\'nin mesleği nedir?', 'Mimar', ['Doktor', 'Pilot', 'Belirlenemez'], 'Ece doktor ve mimar olmadığından pilottur. Nur mimar olmadığından doktordur; geriye kalan mimarlık Ali\'nindir.'),
  ('Bir kuyrukta Elif baştan dördüncü, sondan altıncı sıradadır. Kuyrukta toplam kaç kişi vardır?', '9', ['10', '8', '11'], 'Elif iki sayımda da yer aldığından toplam 4 + 6 − 1 = 9 kişidir.'),
  ('Bir okulun kuralına göre dönem içinde üç kez ödev teslim etmeyen öğrencinin velisi okula çağrılır. Kaan bu dönem üç ödevini teslim etmemiştir. Buna göre hangisi kesinlikle doğrudur?', 'Kaan\'ın velisi okula çağrılır.', ['Kaan dönemi tekrar eder.', 'Kaan\'ın velisi okula hiç çağrılmaz.', 'Kaan başka ödev almaz.'], 'Kuralın koşulu Kaan için gerçekleştiğinden sonucu da gerçekleşir (doğrudan çıkarım). Diğer seçenekler kurala dayanmaz.'),
  ('“Fırın açıksa mutfaktaki uyarı lambası yanar.” bilgisi doğrudur. Şu anda uyarı lambası yanmamaktadır. Buna göre hangisi kesinlikle doğrudur?', 'Fırın şu anda kapalıdır.', ['Fırın şu anda açıktır.', 'Uyarı lambası bozulmuştur.', 'Mutfakta kimse yoktur.'], 'Sonuç (lambanın yanması) gerçekleşmediyse koşul (fırının açık olması) da gerçekleşmemiştir. Bu, geriye doğru çıkarımdır.'),
  ('“Bir tam sayının 6\'ya bölünmesi, 3\'e bölünmesi için yeterlidir.” cümlesinin anlamı hangisidir?', '6\'ya bölünen her tam sayı 3\'e de bölünür.', ['3\'e bölünen her tam sayı mutlaka 6\'ya da bölünür.', '3\'e bölünmeyen sayılar 6\'ya bölünebilir.', '6\'ya bölünmeyen sayılar 3\'e bölünmez.'], '“p, q için yeterlidir” demek “p ise q” demektir. Burada p: 6\'ya bölünmek, q: 3\'e bölünmektir.'),
  ('“Bilet almadıkça kimse konser salonuna giremez.” kuralı eksiksiz uygulanmaktadır. Emre konser salonuna girmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Emre bilet almıştır.', ['Emre konseri sonuna kadar izlemiştir.', 'Emre\'nin bileti indirimlidir.', 'Emre salona görevli olarak girmiştir.'], '“Bilet almadıkça giremez” ifadesi “salona giren herkes bilet almıştır” demektir; Emre de salona girdiğine göre bilet almıştır.'),
  ('Bir halk kütüphanesi yalnızca hafta içi günlerde açıktır. Tuba, kütüphanenin bugün açık olduğunu görmüştür. Buna göre hangisi kesinlikle doğrudur?', 'Bugün hafta içi bir gündür.', ['Bugün cumartesi günüdür.', 'Kütüphane yarın da açık olacaktır.', 'Kütüphane hafta sonu da açılır.'], '“Yalnızca hafta içi açık” demek, açık olduğu her günün hafta içi olduğu anlamına gelir. Yarın hafta sonu olabileceği için o seçenek kesin değildir.'),
  ('Bir kafede kahvaltı menüsü alan herkese ya çay ya da kahve verilir; ikisi birden verilmez. Zehra kahvaltı menüsü almış ve kendisine çay verilmemiştir. Buna göre hangisi kesinlikle doğrudur?', 'Zehra\'ya kahve verilmiştir.', ['Zehra\'ya hem çay hem kahve verilmiştir.', 'Zehra\'ya meyve suyu verilmiştir.', 'Zehra\'ya hiçbir içecek verilmemiştir.'], 'Seçeneklerden biri mutlaka verildiğine göre, çay verilmediyse kahve verilmiştir.'),
  ('Bir dernekte üye olan herkes ya öğrencidir ya da 65 yaşını geçmiştir; iki koşulu birden taşıyan üye de olabilir. Hakan bu derneğin üyesidir ve öğrenci değildir. Buna göre hangisi kesinlikle doğrudur?', 'Hakan 65 yaşını geçmiştir.', ['Hakan 65 yaşından küçüktür.', 'Hakan geçmişte öğrenciydi.', 'Hakan derneğin yöneticisidir.'], 'Üyeler iki özellikten en az birine sahiptir. Hakan\'da öğrencilik olmadığına göre diğer özellik, yani 65 yaşını geçmiş olmak, vardır.'),
  ('Kerem her akşam ya kitap okur ya da film izler. Kitap okuduğu akşamlar geç uyur; film izlediği akşamlar da geç uyur. Bu akşam Kerem için hangisi kesinlikle doğrudur?', 'Kerem bu akşam geç uyuyacaktır.', ['Kerem bu akşam kitap okuyacaktır.', 'Kerem bu akşam film izleyecektir.', 'Kerem bu akşam erken uyuyacaktır.'], 'İki olasılığın ikisi de aynı sonuca götürdüğünden, hangisi seçilirse seçilsin Kerem geç uyur.'),
  ('“Bütün kemancılar müzisyendir.” ve “Bütün müzisyenler nota okuyabilir.” öncülleri doğru kabul edilirse hangi sonuç kesinlikle çıkar?', 'Bütün kemancılar nota okuyabilir.', ['Nota okuyan herkes kemancıdır.', 'Bazı müzisyenler kemancı değildir.', 'Bütün müzisyenler keman çalar.'], 'Kemancılar müzisyenlerin, müzisyenler de nota okuyanların içinde kaldığından kemancılar nota okuyanların içindedir.'),
  ('“Hiçbir sürüngen memeli değildir.” ve “Bütün yılanlar sürüngendir.” bilgilerinden hangi sonuç kesinlikle çıkar?', 'Hiçbir yılan memeli değildir.', ['Bazı yılanlar memelidir.', 'Bütün sürüngenler yılandır.', 'Memeli olmayan her canlı yılandır.'], 'Yılanlar sürüngenler kümesinin içindedir ve bu kümenin memelilerle ortak öğesi yoktur.'),
  ('Bir müzede çalışan bütün rehberlerin en az iki dil bildiği biliniyor. Ayla bu müzede rehberdir. Aşağıdakilerden hangisi verilen bilgilerle çelişir?', 'Ayla yalnızca tek bir dil bilir.', ['Ayla üç dil bilir.', 'Ayla Fransızca bilir.', 'Ayla hafta sonları da müzede rehberlik yapar.'], 'Ayla rehber olduğu için en az iki dil bilmelidir; tek dil bilmesi bu bilgiyle çelişir. Diğerleri verilenlerle uyumludur.'),
  ('Okulun camını Efe, Gizem ya da Hale\'den biri kırmıştır. Efe “Camı Gizem kırdı.”, Gizem “Ben kırmadım.”, Hale “Gizem kırdı.” diyor. Bu üç kişiden yalnızca biri yalan söylüyorsa camı kim kırmıştır?', 'Gizem', ['Efe', 'Hale', 'Belirlenemez'], 'Efe ile Hale aynı şeyi söylediği için ikisi birlikte ya doğru ya yanlıştır. Tek yalancı olduğundan ikisi de doğrudur; camı Gizem kırmıştır ve yalan söyleyen de odur.'),
  ('Elif, Kerem\'e “Annenin tek kardeşi benim annemdir.” diyor. Buna göre Elif, Kerem\'in nesidir?', 'Teyze kızı', ['Hala kızı', 'Yeğeni', 'Teyzesinin gelini'], 'Kerem\'in annesinin kız kardeşi Kerem\'in teyzesidir; Elif bu teyzenin kızıdır.'),
  ('Ayşe\'nin babasının annesi, Ayşe için hangi akrabalık adıyla anılır?', 'Babaanne', ['Anneanne', 'Hala', 'Babasının teyzesi'], 'Babanın annesine babaanne, annenin annesine anneanne denir.'),
  ('Leyla\'nın babasının kız kardeşi Gönül\'dür; Gönül\'ün eşi ise Rıza\'dır. Rıza, Leyla\'nın nesi olur?', 'Eniştesi', ['Amcası', 'Dayısı', 'Kayınbiraderi'], 'Babanın kız kardeşi haladır; halanın eşine enişte denir.'),
  ('Hatice Hanım\'ın oğlu evlenmiştir. Oğlunun eşi, Hatice Hanım\'ın nesi olur?', 'Gelini', ['Yengesi', 'Görümcesi', 'Baldızı'], 'Bir kişinin oğlunun eşine gelin denir. Yenge kardeşin ya da amca/dayının eşidir.'),
  ('Tolga\'nın iki kız kardeşi vardır. Kız kardeşlerin her birinin de yalnızca bir erkek kardeşi vardır. Bu ailede kaç çocuk bulunur?', '3', ['4', '5', '6'], 'Kız kardeşlerin tek erkek kardeşi Tolga\'dır. Ailede Tolga ve iki kız kardeşi olmak üzere üç çocuk vardır.'),
  ('Bir çocuk kuzeye doğru 5 metre yürüyor, sonra sağa dönüp 3 metre, ardından yine sağa dönüp 5 metre yürüyor. Çocuk, başladığı noktaya göre nerededir?', '3 metre doğuda', ['3 metre batıda', '5 metre kuzeyde', 'Başladığı noktada'], 'Kuzeye 5 m çıkıp sağa (doğuya) 3 m gider, sonra yine sağa dönünce güneye bakar ve 5 m inerek başlangıcın 3 m doğusuna gelir.'),
  ('Bir köyün 2 km doğusunda bir göl, gölün 2 km kuzeyinde bir orman, ormanın 2 km batısında da bir köprü vardır. Köprü, köye göre hangi yöndedir?', 'Tam kuzeyinde', ['Tam doğusunda', 'Kuzeydoğusunda', 'Kuzeybatısında'], 'Doğuya 2 km gidilip kuzeye 2 km çıkıldıktan sonra batıya 2 km dönülünce doğu-batı farkı sıfırlanır; köprü köyün 2 km kuzeyinde kalır.'),
  ('Türk alfabesinin 29 harfi (A B C Ç D E F G Ğ H I İ J K L M N O Ö P R S Ş T U Ü V Y Z) kullanılıyor. Bir şifrede her harf, alfabede kendisinden hemen sonra gelen harfle değiştirilir. Bu şifreyle KUŞ sözcüğü nasıl yazılır?', 'LÜT', ['LUT', 'JTS', 'LÜS'], 'K\'den sonra L, U\'dan sonra Ü, Ş\'den sonra T gelir. Türk alfabesinde U ile Ü ayrı harflerdir.'),
  ('Bir şifrede KALEM sözcüğü MELAK, KAVUN sözcüğü de NUVAK olarak yazılmıştır. Aynı kurala göre DOLAP sözcüğü nasıl yazılır?', 'PALOD', ['PADOL', 'LOPAD', 'DPALO'], 'Kural, sözcüğün harflerini tersten yazmaktır. DOLAP tersten okununca PALOD olur.'),
  ('Uydurma bir dilde “mavi gök” ifadesi “tu ra”, “mavi deniz” ifadesi “ra zek”, “derin deniz” ifadesi ise “zek po” biçiminde söylenmektedir. Sözcüklerin sırası önemli değilse bu dilde “derin” sözcüğünün karşılığı hangisidir?', 'po', ['zek', 'ra', 'tu'], '“mavi” ilk iki ifadede ortaktır: ra. “deniz” son iki ifadede ortaktır: zek. Geriye “derin” için po kalır.'),
  ('İngiliz alfabesine göre yazılmış AZ, BY, CX, … dizisinin bir sonraki terimi hangisidir?', 'DW', ['DX', 'EW', 'DV'], 'İlk harfler baştan ilerler (A, B, C, D), ikinci harfler sondan geriye gelir (Z, Y, X, W).'),
  ('2B, 4D, 6F, … dizisinin bir sonraki terimi aşağıdakilerden hangisidir? (İngiliz alfabesi kullanılmaktadır.)', '8H', ['8G', '7H', '9I'], 'Sayılar 2\'şer artar; harfler de alfabede birer atlayarak ilerler. Her terimdeki harf, sayının alfabedeki karşılığıdır (8. harf H).'),
  ('Bir dizide kare, daire ve üçgen sözcükleri bu sırayla durmadan tekrar ediyor: kare, daire, üçgen, kare, daire, üçgen, … Bu dizinin 20. terimi hangisidir?', 'Daire', ['Kare', 'Üçgen', 'Yıldız'], 'Desen üçlü olarak tekrarlanır. 20\'nin 3\'e bölümünden kalan 2 olduğundan 20. terim desenin ikinci öğesidir.'),
  ('Bir şifrede her sözcüğün harfleri alfabetik sıraya göre diziliyor; örneğin KALEM sözcüğü AEKLM olarak yazılıyor. Buna göre TOPRAK sözcüğü nasıl yazılır?', 'AKOPRT', ['AKORPT', 'AOKPRT', 'AKOPTR'], 'TOPRAK\'taki harfler A, K, O, P, R, T\'dir ve alfabetik sırayla AKOPRT olarak dizilir.'),
  ('“Pınar bir veteriner olduğuna göre hayvanları seviyordur.” sonucuna ulaşmak için hangi öncülün kabul edilmesi gerekir?', 'Bütün veterinerler hayvanları sever.', ['Hayvanları seven herkes veteriner olur.', 'Pınar\'ın evinde bir kedisi vardır.', 'Veterinerlerin çoğu köpek besler.'], 'Sonuç, veterinerlik ile hayvan sevgisi arasında genel bir kural varsayar: bütün veterinerler hayvanları sever. “Hayvan seven herkes veteriner olur.” ifadesi bu kuralın tersidir.'),
  ('“Sen de her gün sigara içiyorsun; bana sigaranın zararlarını anlatmaya hakkın yok.” sözünde hangi akıl yürütme hatası yapılmıştır?', 'Sen de safsatası', ['Yanlış ikilem', 'Kaygan zemin safsatası', 'Çoğunluğa başvurma'], 'Konuşan, sigaranın zararlı olup olmadığını tartışmak yerine karşısındakinin de aynı şeyi yaptığını öne sürer. Bu, iddianın doğruluğunu etkilemez.'),
  ('Soldan sağa 1\'den 4\'e kadar numaralı dört kutunun her birinde bir top vardır: kırmızı, yeşil, mavi ve sarı. Kırmızı top, yeşil topun hemen solundaki kutudadır. Mavi top 1 numaralı kutuda değildir. Sarı top 4 numaralı kutudadır. Mavi top kaç numaralı kutudadır?', '3', ['1', '2', '4'], 'Sarı 4\'te olduğundan kırmızı-yeşil ikilisi 1-2 ya da 2-3\'tedir. 2-3 olursa mavi 1\'e düşer, bu yasaktır. Öyleyse kırmızı 1, yeşil 2, mavi 3\'tedir.'),
  ('A, B ve C kutularına toplam 6 bilye konmuştur. Her kutuda en az bir bilye vardır; A kutusunda B\'dekinden, B kutusunda da C\'dekinden daha çok bilye bulunur. A kutusunda kaç bilye vardır?', '3', ['2', '4', '5'], 'C en az 1, B en az 2, A en az 3 olmalıdır; bu en küçük değerlerin toplamı zaten 6\'dır. Bu yüzden dağılım 3, 2, 1 olmak zorundadır.'),
  ('Selin, Tuğba\'dan uzundur. Tuğba da Ufuk\'tan uzundur. Bu bilgilere göre aşağıdakilerden hangisi imkânsızdır?', 'Ufuk, Selin\'den uzundur.', ['Tuğba, Selin\'den daha kısadır.', 'Selin\'in boyu tam 180 santimetredir.', 'Ufuk, sınıfının en kısa öğrencisidir.'], 'Selin > Tuğba > Ufuk sıralamasında Ufuk\'un Selin\'den uzun olması olanaksızdır. Boy ölçüsü ya da sınıftaki konum bilgilerle çelişmez.'),
  ('Tarih, coğrafya ve felsefe sınavları pazartesi, salı ve çarşamba günlerine birer tane olacak biçimde yerleştirilecektir. Tarih sınavı salı günü olmayacak, felsefe sınavı coğrafyadan önce yapılacak ve coğrafya çarşambaya konmayacaktır. Çarşamba günü hangi sınav yapılır?', 'Tarih', ['Coğrafya', 'Felsefe', 'Belirlenemez'], 'Coğrafya çarşamba olamaz ve felsefeden sonra gelmelidir; o hâlde coğrafya salı, felsefe pazartesidir. Geriye kalan çarşambaya tarih yerleşir.'),
  ('Kırmızı kutu mavi kutunun içinde, yeşil kutu kırmızı kutunun içindedir. Sarı kutu ise mavi kutuyu içine almaktadır. En içte hangi kutu bulunur?', 'Yeşil', ['Kırmızı', 'Mavi', 'Sarı'], 'İçten dışa sıralama yeşil, kırmızı, mavi, sarı biçimindedir.'),
  ('Kerem\'in kalem kutusunda yalnızca mavi ve kırmızı kalemler vardır ve kırmızı kalemlerin sayısı mavilerden fazladır. Buna göre hangisi kesinlikle doğrudur?', 'Kutuda en az bir kırmızı kalem vardır.', ['Kutuda en az bir tane mavi kalem bulunur.', 'Kalemlerin yarısından azı kırmızı renktedir.', 'Kutudaki kalemlerin sayısı tek bir sayıdır.'], 'Mavi kalem sayısı sıfır bile olsa kırmızılar ondan fazla olacağı için en az bir kırmızı kalem bulunur. Mavi kalem olmayabilir; toplam çift de olabilir.'),
  ('Ali, Banu ve Cem bir satranç turnuvasında birbirleriyle birer kez oynamış, hiçbir oyun berabere bitmemiştir. Ali iki oyununu da kazanmış, Banu da Cem\'i yenmiştir. Turnuvada hiç oyun kazanamayan kimdir?', 'Cem', ['Ali', 'Banu', 'Herkes en az bir oyun kazanmıştır'], 'Ali hem Banu\'yu hem Cem\'i yenmiştir. Banu da Cem\'i yendiğine göre Cem iki oyununu da kaybetmiştir.'),
  ('Bir çekmecede birbirine karışmış 5 siyah ve 5 beyaz çorap vardır. Karanlıkta çekmeceden en az kaç çorap alınırsa aynı renkten bir çiftin elde olduğu garanti edilir?', '3', ['2', '6', '11'], 'İki çorap farklı renkte çıkabilir. Üçüncü çorap mutlaka bu iki renkten biriyle eşleşir.'),
  ('Bir çiftçi kurt, keçi ve lahanayı küçük bir sandalla nehrin karşısına geçirecektir. Sandala çiftçiyle birlikte yalnızca biri sığar. Çiftçi yokken kurt keçiyi, keçi de lahanayı yer. Çiftçi ilk geçişte yanına hangisini almalıdır?', 'Keçi', ['Kurt', 'Lahana', 'Yalnız kendisi geçmeli'], 'Kurt götürülürse keçi lahanayı, lahana götürülürse kurt keçiyi yer. Yalnızca keçi götürüldüğünde geride kalan kurt ile lahana birbirine zarar vermez.'),
  ('Ayla eve geldiğinde kedi mamasını çoktan bitirmişti. Kedi mamasını, Bora evden çıktıktan sonra yemişti. Bora da evden postacı kapıya geldikten sonra çıkmıştı. Bu olaylardan hangisi en önce gerçekleşmiştir?', 'Postacının gelmesi', ['Bora\'nın evden çıkması', 'Kedinin mamasını yemesi', 'Ayla\'nın eve dönüp gelmesi'], 'Sıralama sondan başa kurulur: Ayla gelir ← kedi yer ← Bora çıkar ← postacı gelir. En önce olan, postacının gelmesidir.'),
  ('Cem sinemaya film başlamadan önce girmiştir. Deniz ise filmin başlamasından sonra gelmiştir. Ece, Cem\'den önce sinemaya gelmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Ece, Deniz\'den önce gelmiştir.', ['Deniz, Cem\'den önce sinemaya gelmiştir.', 'Ece, film başladıktan sonra salona gelmiştir.', 'Cem salona gelenlerin en sonuncusudur.'], 'Ece < Cem < filmin başlaması < Deniz sıralaması oluşur. Ece\'nin Deniz\'den önce geldiği bu zincirden doğrudan çıkar.'),
  ('Bir müzedeki hırsızlığın, bekçinin turunu bitirmesinden sonra ama ışıkların kapanmasından önce olduğu anlaşılmıştır. Bekçi turunu 22.00\'de bitirmiş, ışıklar 23.30\'da kapanmıştır. Hırsızlık aşağıdaki saatlerden hangisinde olmuş olabilir?', '22.45', ['21.50', '23.45', '21.15'], 'Olay 22.00 ile 23.30 arasında olmalıdır. Bu aralıkta kalan tek saat 22.45\'tir.'),
  ('Murat sabahları okula gitmeden önce kahvaltı eder. Kahvaltıdan önce duş alır. Kedisini ise duştan sonra ama kahvaltıdan önce besler. Murat\'ın sabah yaptığı dört işten üçüncüsü hangisidir?', 'Kahvaltı etmek', ['Kedisini beslemek', 'Duş almak', 'Okula gitmek'], 'Sıra duş, kediyi besleme, kahvaltı ve okula gitme biçimindedir. Üçüncü iş kahvaltıdır.'),
  ('Bir araştırmacının hipotezi “Bu göldeki bütün kuğular beyazdır.” biçimindedir. Aşağıdaki gözlemlerden hangisi bu hipotezi çürütür?', 'Gölde tek bir siyah kuğu görülmesi', ['Gölde yüz beyaz kuğu sayılması', 'Komşu gölde gri bir kaz görülmesi', 'Gölde beyaz kuğuların yanında beyaz bir ördek görülmesi'], 'Genel bir “bütün” yargısını çürütmek için tek bir karşı örnek yeterlidir. Ne kadar çok beyaz kuğu görülse de hipotez kesin olarak kanıtlanmış olmaz.'),
  ('Bir postanede “Kırmızı zarfların hepsinin içinde bir pul bulunur.” kuralı vardır. Aşağıdakilerden hangisi bu kuralın çiğnendiğini gösterir?', 'İçinde pul olmayan kırmızı bir zarf', ['İçinde pul bulunan beyaz bir zarf', 'İçinde pul olmayan beyaz bir zarf', 'İçinde iki ayrı pul bulunan kırmızı bir zarf'], 'Kural yalnızca kırmızı zarflar hakkındadır ve onlarda pul bulunmasını şart koşar. Beyaz zarfların içeriği ya da fazladan pul kuralı bozmaz.'),
  ('Bir müzede eserler şöyle yerleştiriliyor: ahşaptan yapılmış ve 1900\'den önce üretilmiş eserler A salonuna, ahşaptan yapılmış ve 1900\'den sonra üretilmiş eserler B salonuna, ahşap olmayan bütün eserlerin yeri ise C salonudur. 1925 yılında yapılmış bronz bir heykel hangi salona konur?', 'C salonuna', ['A salonuna', 'B salonuna', 'A ya da B salonuna'], 'Eserin malzemesi ahşap olmadığı için üretim yılına bakılmaz; ahşap olmayan her eser C salonuna gider.'),
  ('Bir kargo şirketinin tarifesi şöyledir: Şehir içi gönderilerde 5 kg\'dan hafif paketler 50 lira, 5 kg ve üzeri paketler 80 liradır. Şehir dışı gönderilerde 10 kg\'a kadar paketler 120 lira, 10 kg\'dan ağır paketler 150 liradır. Şehir dışına gönderilen 12 kg\'lık bir paket kaç liraya gönderilir?', '150 TL', ['120 TL', '80 TL', '200 TL'], 'Gönderi şehir dışına olduğu için ikinci kural grubu uygulanır; paket 10 kg\'dan ağır olduğundan ücret 150 liradır.'),
  ('Bir ödül şu üç koşulu birlikte sağlayan öğrenciye verilecektir: kız öğrenci olmak, gözlük kullanmamak ve sınıf başkanı olmamak. Adaylar: Ayşe (kız, gözlüklü), Berk (erkek, gözlüksüz, başkan değil), Ceren (kız, gözlüksüz, başkan değil), Duru (kız, gözlüksüz, sınıf başkanı). Ödülü kim alır?', 'Ceren', ['Ayşe', 'Berk', 'Duru'], 'Ayşe gözlüklü, Berk erkek, Duru ise sınıf başkanı olduğu için elenir. Üç koşulu birden sağlayan yalnızca Ceren\'dir.'),
  ('“Kalem : yazmak” ilişkisinin benzeri aşağıdakilerden hangisinde vardır?', 'Makas : kesmek', ['Kâğıt : defter', 'Silgi : kalem', 'Boya : renk'], 'Kalem yazmak için kullanılan bir araçtır; makas da kesmek için kullanılan bir araçtır. Diğer ikililerde araç-işlev ilişkisi yoktur.'),
  ('“Pilot : uçak” ikilisindeki ilişkiyle aynı ilişkiyi taşıyan ikili hangisidir?', 'Kaptan : gemi', ['Yolcu : tren', 'Kanat : uçak', 'Hostes : havaalanı'], 'Pilot uçağı, kaptan gemiyi yöneten kişidir. Yolcu taşıtı yönetmez; kanat ise uçağın bir parçasıdır.'),
  ('“Sayfa : kitap” ilişkisine göre “? : orman” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Ağaç', ['Toprak', 'Yaprak', 'Ormancı'], 'Sayfa kitabı oluşturan birimdir; ormanı oluşturan birim de ağaçtır. Yaprak ormanın değil ağacın parçasıdır.'),
  ('Bir koşuda üçüncü sırada giden Cem önce iki koşucuyu geçmiş, ardından bir koşucu da onu geçmiştir. Cem şu anda kaçıncı sıradadır?', '2', ['1', '3', '4'], 'İki kişiyi geçince birinci sıraya çıkar. Ardından bir kişi onu geçince ikinci sıraya düşer.'),
  ('Bir yarışta ikinci sırada koşan atleti geçen bir koşucu, geçtiği anda kaçıncı sıraya yükselmiş olur?', 'İkinci sıraya', ['Birinci sıraya', 'Üçüncü sıraya', 'Kesin olarak belirlenemez'], 'İkinci sıradakini geçen kişi onun yerini alır; önünde hâlâ birinci sıradaki koşucu vardır.'),
  ('Bir odada ışık yanıyorsa düğme açıktır; düğme açıksa ışık yanar. Şu anda odadaki ışık yanmamaktadır. Buna göre düğmenin durumu nedir?', 'Düğme kapalıdır.', ['Düğme açıktır.', 'Düğme bozuktur.', 'Düğmenin durumu bilinemez.'], 'İki yönlü koşul vardır: ışığın yanması ile düğmenin açık olması aynı anda gerçekleşir. Işık yanmıyorsa düğme açık olamaz.'),
  ('Babası Ece\'ye “Odanı toplarsan akşam sinemaya gideriz.” demiştir. Ece odasını toplamış ama akşam sinemaya gidilmemiştir. Bu durum için ne söylenebilir?', 'Babası verdiği sözü tutmamıştır.', ['Ece odasını yeterince toplamamıştır.', 'Babasının sözü yerine getirilmiştir.', 'Ece toplamasaydı sinemaya gidilirdi.'], 'Koşul (odanın toplanması) gerçekleştiği hâlde sonuç (sinema) gerçekleşmemiştir; koşullu söz yalnızca bu durumda çiğnenmiş olur.'),
  ('Burak şunları biliyor: Saat 7\'de kalkarsa servisi yakalar. Servisi yakalarsa derse geç kalmaz. Derse geç kalmazsa yoklamada adı okunur. Burak bu sabah saat 7\'de kalkmıştır. Buna göre hangisi kesinlikle doğrudur?', 'Yoklamada Burak\'ın adı okunur.', ['Burak derse yine geç kalmıştır.', 'Burak servisi kaçırıp yürümüştür.', 'Burak öğleden önce eve dönmüştür.'], 'Koşul zinciri ileri doğru izlenir: 7\'de kalkma → servis → geç kalmama → yoklamada adın okunması.'),
  ('Bir okulda her öğrenci en az bir kulübe üyedir. Kulüplere üye olanlar cuma öğleden sonra ders almaz. Buna göre hangisi kesinlikle doğrudur?', 'Bu okulda hiçbir öğrenci cuma öğleden sonra ders almaz.', ['Bazı öğrencilerin cuma öğleden sonra yine de ders aldığı bilinir.', 'Kulüplere yalnızca öğrenciler üye olabilir.', 'Cuma ders almayan herkes bir kulübe üyedir.'], 'Her öğrenci bir kulübe üye, her kulüp üyesi de cuma öğleden sonra ders dışıdır; dolayısıyla bütün öğrenciler için bu durum geçerlidir.'),
  ('“Kemal İzmir\'dedir.” ve “Kemal Bursa\'dadır.” cümlelerinden en az birinin doğru olduğu biliniyor. Daha sonra Kemal\'in Bursa\'da olmadığı öğreniliyor. Buna göre hangisi kesinlikle doğrudur?', 'Kemal şu an İzmir\'de bulunuyor.', ['Kemal hem İzmir\'de hem Bursa\'dadır.', 'Kemal ne İzmir\'de ne Bursa\'dadır.', 'Kemal üçüncü bir kentte bulunmaktadır.'], 'İki seçenekten en az biri doğru olduğuna ve Bursa seçeneği elendiğine göre doğru olan İzmir seçeneğidir.'),
  ('Ali, Bora, Cem ve Dila\'nın her birinin farklı bir evcil hayvanı vardır: kedi, köpek, kuş ve balık. Ali\'nin kedisi ya da köpeği yoktur. Bora kuş beslemez. Balık Ali\'ye ait değildir. Köpek Cem\'indir. Ali hangi hayvanı beslemektedir?', 'Kuş', ['Kedi', 'Balık', 'Köpek'], 'Ali\'ye kedi, köpek ve balık yasaktır; geriye kuş kalır. Bora ile Dila\'nın kedi ve balığı nasıl paylaştığı ise bu bilgilerle belirlenemez.'),
  ('Aydın, Berna, Cahit ve Dilek öğretmenler; matematik, fizik, kimya ve biyolojiden farklı birer ders veriyor. Aydın ne fizik ne de kimya öğretir. Biyolojiyi Berna verir. Cahit fizik dersine girmez. Dilek hangi dersi öğretir?', 'Fizik', ['Kimya', 'Matematik', 'Biyoloji'], 'Biyoloji Berna\'da olduğundan Aydın matematik öğretir. Cahit fizik vermediği için kimyayı alır; fizik Dilek\'e kalır.'),
  ('Nur\'un annesinin babası Hasan Bey\'dir. Hasan Bey\'in tek oğlu Kerim\'dir. Kerim, Nur\'un nesidir?', 'Dayısı', ['Amcası', 'Eniştesi', 'Dedesi'], 'Kerim, Nur\'un annesinin erkek kardeşidir. Annenin erkek kardeşine dayı denir.'),
  ('Ayşe\'nin tek erkek kardeşi Mehmet\'tir. Mehmet\'in kızı, Ayşe\'ye hangi akrabalık adıyla seslenir?', 'Hala', ['Teyze', 'Yenge', 'Abla'], 'Ayşe, Mehmet\'in kız kardeşidir. Bir çocuk babasının kız kardeşine hala der.'),
  ('Can\'ın eşi Seda\'dır. Seda\'nın kız kardeşi Can\'ın nesi olur?', 'Baldızı', ['Görümcesi', 'Yengesi', 'Eltisi'], 'Bir erkeğin eşinin kız kardeşine baldız denir. Görümce ise bir kadının eşinin kız kardeşidir.'),
  ('Doğuya bakan bir öğrenci önce üç kez sağa, ardından iki kez sola dönüyor; her dönüş 90 derecedir. Öğrenci şimdi hangi yöne bakmaktadır?', 'Güneye', ['Kuzeye', 'Batıya', 'Doğuya'], 'Üç sağ ile iki sol dönüş birbirini götürünce net olarak bir sağ dönüş kalır. Doğuya bakan biri sağa dönünce güneye bakar.'),
  ('Yarından iki gün önce salı olduğuna göre bugün haftanın hangi günüdür?', 'Çarşamba', ['Perşembe', 'Pazartesi', 'Salı'], 'Yarından iki gün önce, dün demektir. Dün salı ise bugün çarşambadır.'),
  ('İngiliz alfabesi kullanılan bir şifrede her harf, alfabedeki sıra numarasının iki katıyla gösteriliyor. Örneğin CAB sözcüğü 6-2-4 olarak yazılıyor. Bu şifreye göre BED sözcüğü nasıl yazılır?', '4-10-8', ['2-5-4', '4-10-6', '4-8-10'], 'B 2., E 5., D 4. harftir. Bu sayıların iki katı 4, 10 ve 8\'dir.'),
  ('Bir şifrede sözcüğün yalnızca ilk ve son harfi yer değiştiriyor; örneğin KAPI sözcüğü IAPK oluyor. Aynı kurala göre MASA nasıl yazılır?', 'AASM', ['ASAM', 'MASA', 'SAMA'], 'M ile son harf A yer değiştirir, ortadaki A ve S yerinde kalır: A-A-S-M.'),
  ('Bir sözcük oyununda her sözcük, bir öncekinin son harfiyle başlamak zorundadır. Oyun “elma, armut, tuz” diye sürmektedir. Sıradaki sözcük aşağıdakilerden hangisi olabilir?', 'zil', ['kale', 'nar', 'ekmek'], '“tuz” sözcüğü z harfiyle bittiği için sıradaki sözcük z ile başlamalıdır.'),
  ('Bir şifrede cümledeki her sözcük tersten yazılıyor ama sözcüklerin sırası değişmiyor; örneğin “BEN GELDİM” ifadesi “NEB MİDLEG” oluyor. Buna göre “SU AKAR” ifadesi nasıl yazılır?', 'US RAKA', ['RAKA US', 'SU RAKA', 'US AKAR'], 'Her sözcük kendi içinde ters çevrilir: SU → US, AKAR → RAKA. Sözcüklerin yeri ise korunur.'),
  ('İngiliz alfabesine göre yazılmış AB, DE, GH, … dizisinin bir sonraki terimi hangisidir?', 'JK', ['IJ', 'KL', 'HI'], 'Her terim iki ardışık harften oluşur ve terimler arasında birer harf atlanır (C, F, I atlanmıştır). Sıradaki terim JK\'dir.'),
  ('“Ayşe\'nin bisikleti Can\'ınkinden daha pahalı; öyleyse Ayşe\'nin bisikleti daha kalitelidir.” akıl yürütmesindeki örtük varsayım hangisidir?', 'Fiyat, kalitenin güvenilir bir göstergesidir.', ['Ayşe bisikletini Can\'dan daha sık kullanır.', 'İki bisiklet de aynı mağazadan satın alınmıştır.', 'Can\'ın bisikleti Ayşe\'ninkinden daha eskidir.'], 'Pahalılıktan kaliteye geçebilmek için fiyatın kaliteyi yansıttığı kabul edilmelidir.'),
  ('“Gece yağmur yağmış olmalı; çünkü sabah yollar ıslaktı ve sokak yıkama aracı bu hafta çalışmıyor.” akıl yürütmesinde varılan sonuç hangisidir?', 'Gece yağmur yağdığı', ['Sabah yolların ıslak olduğu', 'Yıkama aracının bu hafta çalışmadığı', 'Sokakların bu hafta hiç temizlenmediği'], '“Çünkü” sözcüğünden sonra gelenler gerekçelerdir. Gerekçelerle desteklenen yargı, gece yağmurun yağmış olduğudur.'),
  ('Bir yönetici toplantıda “Bu projeyi onaylamazsanız gece gündüz çalışan ekibimizin yüzündeki hayal kırıklığını bir düşünün.” diyor. Bu sözde hangi akıl yürütme hatası yapılmıştır?', 'Duygulara başvurma', ['Bölme hatası', 'Döngüsel akıl yürütme', 'Aceleci genelleme'], 'Projenin değeri hakkında kanıt sunulmamış, dinleyicilerin acıma duygusu harekete geçirilmeye çalışılmıştır.'),
  ('Ali ile Can aynı boydadır. Can, Ece\'den uzundur. Ece de Nur\'dan uzundur. Bu dört kişiden en kısası kimdir?', 'Nur', ['Ece', 'Can', 'Ali'], 'Ali = Can > Ece > Nur sıralaması oluşur; en kısa Nur\'dur.'),
  ('Bir kan merkezinde bağış yapabilmek için 18 ile 65 yaş arasında olmak, en az 50 kilogram gelmek ve son üç ay içinde bağış yapmamış olmak gerekir. Aday 1: 17 yaşında, 60 kg, hiç bağış yapmamış. Aday 2: 40 yaşında, 48 kg, hiç bağış yapmamış. Aday 3: 30 yaşında, 70 kg, iki ay önce bağış yapmış. Aday 4: 52 yaşında, 65 kg, son bağışı bir yıl önce. Hangi aday bağış yapabilir?', 'Dördüncü aday', ['Birinci aday', 'Üçüncü aday', 'Hiçbir aday bağış yapamaz'], 'Aday 1 yaş, Aday 2 kilo, Aday 3 de son bağış süresi koşulunu sağlamaz. Üç koşulu birden sağlayan yalnızca Aday 4\'tür.'),
  ('Bir okul kütüphanesinde öğrenciler en çok 3, öğretmenler en çok 5 kitap ödünç alabilir; teslim tarihi geçmiş kitabı olan hiç kimse yeni kitap alamaz. Aşağıdakilerden hangisi aynı anda 4 kitap ödünç alabilir?', 'Gecikmiş kitabı olmayan bir öğretmen', ['Gecikmiş kitabı olmayan bir öğrenci', 'Bir kitabı gecikmiş bir öğretmen', 'Gecikmiş kitabı olan bir öğrenci'], '4 kitap öğrenci sınırını aşar; bu yüzden kişi öğretmen olmalıdır. Ayrıca gecikmiş kitabı bulunmamalıdır.'),
  ('Bir kulüp seçiminde oy kullanabilmek için en az bir yıllık üye olmak ve aidat borcu bulunmamak gerekir. Kemal 3 yıllık üyedir ve iki aylık aidat borcu vardır. Lale 8 aylık üyedir ve borcu yoktur. Murat 2 yıllık üyedir ve borcu yoktur. Nesrin 5 yıllık üyedir ve bir aylık borcu vardır. Kimler oy kullanabilir?', 'Yalnızca Murat', ['Murat ile Lale', 'Kemal ile Murat', 'Murat ile Nesrin'], 'Kemal ve Nesrin\'in aidat borcu vardır; Lale ise henüz bir yılı doldurmamıştır. İki koşulu da sağlayan yalnızca Murat\'tır.'),
  ('Bir kurul, başkan toplantıdaysa en az 5 üyeyle, başkan toplantıda değilse en az 6 üyeyle karar alabilir. Bir toplantıya başkan dışında 5 üye katılmış, başkan gelmemiştir. Bu toplantı için hangisi doğrudur?', 'Kurul bu toplantıda karar alamaz.', ['Kurul bu toplantıda karar alabilir.', 'Kurulun 6 üyesi toplantıdadır.', 'Toplantıya başkan da katılmıştır.'], 'Başkan olmadığı için gereken sayı 6\'dır. 5 üye bu sayıya ulaşmadığından karar alınamaz.'),
  ('Bir tren 14.20\'de kalkacaktır. Ali\'nin evinden istasyona varması 35 dakika, istasyonda bilet alması 10 dakika sürüyor. Treni kaçırmamak için Ali evden en geç saat kaçta çıkmalıdır?', '13.35', ['13.45', '13.40', '13.25'], 'Toplam 45 dakikaya ihtiyacı vardır. 14.20\'den 45 dakika geriye gidilince 13.35 bulunur.'),
  ('Bir torbada yalnızca kırmızı ve mavi bilyeler vardır. Torbadan bakmadan iki bilye çekilmiş ve ikisinin de kırmızı olduğu görülmüştür. Buna göre çekilişten önceki torba için hangisi kesinlikle doğrudur?', 'Torbada en az iki kırmızı bilye vardı.', ['Torbada hiç mavi bilye yoktu.', 'Kırmızı bilyelerin sayısı mavilerden kesinlikle fazlaydı.', 'Torbada tam iki kırmızı bilye vardı.'], 'Çekilen iki bilye kırmızı olduğuna göre torbada en az iki kırmızı vardı. Mavilerin sayısı ya da kırmızıların mavilerden çok olup olmadığı bilinemez.'),
  ('Bir dükkândaki bütün kazaklar ya mavi ya da gridir. Mavi kazakların hepsi yünlüdür. Ayşe bu dükkândan yünlü olmayan bir kazak almıştır. Ayşe\'nin aldığı kazak hangi renktir?', 'Gri', ['Mavi', 'Kırmızı', 'Belirlenemez'], 'Kazak yünlü olmadığına göre mavi olamaz; dükkânda yalnızca iki renk bulunduğundan kazak gridir.'),
  ('Aşağıdaki ifadelerden hangisi bir gözlem değil, bir çıkarımdır?', 'Kedi aç olduğu için miyavlıyor.', ['Kedi yüksek sesle miyavlıyor.', 'Kedinin mama kabı mutfakta boş duruyor.', 'Kedi mutfağa doğru yürüyor.'], 'Miyavlama, boş kap ve yürüme doğrudan görülüp duyulabilir. Kedinin aç olduğu ise bu gözlemlerden yapılan bir yorumdur.'),
  ('Bir öğrenci yalnızca üç yakın arkadaşına sorduktan sonra “Okuldaki herkes yeni kantin menüsünü seviyor.” sonucuna varmıştır. Bu sonucun en büyük sorunu nedir?', 'Örneklem küçüktür ve okulu temsil etmeyebilir.', ['Sorular arkadaşlara yüz yüze sorulmuştur.', 'Kantin menüsü yakın zamanda değişmiştir.', 'Arkadaşları aynı sınıfta okuduğu için sonuç kesindir.'], 'Üç kişinin görüşü yüzlerce öğrencinin görüşünü yansıtmaz; üstelik yakın arkadaşlar benzer zevklere sahip olabilir.'),
  ('“Ali her pazartesi yüzmeye gider.” genellemesini çürüten gözlem hangisidir?', 'Ali\'nin bir pazartesi yüzmeye gitmemesi', ['Ali\'nin bir salı günü yüzmeye gitmesi', 'Ali\'nin bir pazartesi yüzmenin yanında koşuya da gitmesi', 'Ali\'nin pazar günü evde dinlenmesi'], 'Genelleme yalnızca pazartesileri kapsar. Yüzmeye gidilmeyen tek bir pazartesi onu çürütür; başka günlerde yapılanlar kuralı ilgilendirmez.'),
  ('Bir müzedeki olay saat 9.00\'da gerçekleşmiştir. Güvenilir bir görevli, aynı saatte Ece\'nin şehrin öbür ucundaki kütüphanede kitap okuduğunu doğrulamıştır. Ece hakkında hangisi söylenebilir?', 'Olayı gerçekleştiren kişi Ece olamaz.', ['Olayı Ece gerçekleştirmiştir.', 'Ece olaydan sonra müzeye gidip ortadan kaybolmuştur.', 'Ece kütüphanede hiç bulunmamıştır.'], 'Bir kişi aynı anda iki farklı yerde bulunamaz. Ece 9.00\'da kütüphanede olduğuna göre müzedeki olayın faili olamaz.'),
  ('Bir konser gecesinde şunlar oldu: Kapılar kapandıktan sonra ışıklar karardı. Işıklar karardıktan sonra perde açıldı ve konser perde açılır açılmaz başladı. İlk alkış ise perde açıldıktan sonra geldi. Bu olaylardan en son hangisi olmuştur?', 'İlk alkışın gelmesi', ['Kapıların kapanması', 'Işıkların kararması', 'Perdenin açılıp konserin başlaması'], 'Sıra kapılar, ışıklar, perde (ve konserin başlaması) ve alkış biçimindedir.'),
  ('Bir pansiyonda 10 oda vardır ve bir gece 11 misafir kalmıştır. Her odada en çok iki kişi kalabiliyorsa aşağıdakilerden hangisi kesinlikle doğrudur?', 'En az bir odada iki misafir kalmıştır.', ['Her odada en az bir misafir vardır.', 'Tam olarak bir oda boş kalmıştır.', 'En az iki odada ikişer misafirin kaldığı kesindir.'], '11 kişi 10 odaya birer birer yerleşse bir kişi açıkta kalır; bu yüzden en az bir oda iki kişiyle dolmuştur. Boş oda olup olmadığı bilinemez.'),
  ('“Termometre : sıcaklık” ilişkisine göre “barometre : ?” ikilisinde soru işaretinin yerine hangisi gelir?', 'Basınç', ['Nem', 'Rüzgâr', 'Yağış'], 'Termometre sıcaklığı, barometre de hava basıncını ölçen araçtır. Nem higrometreyle ölçülür.'),
  ('“Usta : çırak” ilişkisine en çok benzeyen ikili hangisidir?', 'Öğretmen : öğrenci', ['Doktor : hastane', 'Kalem : defter', 'Yazar : kitap'], 'Usta çırağına bir işi öğretir; öğretmen de öğrencisine öğretir. Diğer ikililerde öğreten-öğrenen ilişkisi yoktur.'),
  ('Bir kadının eşinin babası, o kadın için hangi akrabalık adıyla anılır?', 'Kayınpeder', ['Enişte', 'Kayınbirader', 'Dede'], 'Eşin babasına kayınpeder, eşin erkek kardeşine kayınbirader denir.'),
  ('Saat 10.00\'da başlayan bir iş 7 saat 45 dakika sürmüştür. İş saat kaçta bitmiştir?', '17.45', ['17.15', '18.15', '16.45'], '10.00\'a 7 saat eklenince 17.00, 45 dakika daha eklenince 17.45 olur.'),
  ('“Toplantıya ne Ali ne de Veli geldi.” cümlesi doğruysa aşağıdakilerden hangisi kesinlikle doğrudur?', 'Ali toplantıya gelmemiştir.', ['Ali ile Veli\'den biri gelmiştir.', 'Yalnızca Veli toplantıya gelmiştir.', 'İkisi de toplantıya geç kalmıştır.'], '“Ne … ne …” yapısı iki kişinin de gelmediğini bildirir. Bu yüzden Ali\'nin gelmediği kesindir.'),
  ('Bir sınava girebilmek için hem kimlik kartı hem de sınav giriş belgesi göstermek gerekir. Cem giriş belgesini yanına almış ama kimlik kartını evde unutmuştur. Cem için hangisi doğrudur?', 'Cem bu sınava giremez.', ['Cem sınava girebilir.', 'Cem sınavdan geçecektir.', 'Cem\'in belgesi geçersizdir.'], 'İki belge birlikte istenmektedir. Biri eksik olduğunda koşul sağlanmaz.'),
  ('Ali ve Can\'dan en fazla birinin yalan söylediği biliniyor. Ali\'nin yalan söylediği ortaya çıkmıştır. Can için hangisi kesindir?', 'Can doğru söylemektedir.', ['Can da yalan söylemektedir.', 'Can\'ın ne söylediği bilinemez.', 'Can sessiz kalmıştır.'], 'En fazla bir yalancı olabileceğinden ve bu kişi Ali olduğundan Can yalan söyleyemez.'),
  ('Bir odadaki üç lambadan tam ikisi yanmaktadır. Birinci lambanın sönük olduğu görülmüştür. Buna göre hangisi doğrudur?', 'İkinci ve üçüncü lambalar yanmaktadır.', ['Yalnızca ikinci lamba yanmaktadır.', 'Üç lamba da şu anda sönük durumdadır.', 'Yalnızca üçüncü lamba yanmaktadır.'], 'Yanan iki lamba birinci lamba olamayacağına göre geriye kalan iki lambanın ikisi de yanıyor olmalıdır.'),
  ('Bir şifrede ünlüler sayılarla gösterilir: A=1, E=2, I=3, İ=4, O=5, Ö=6, U=7, Ü=8; ünsüzler olduğu gibi yazılır. Bu şifreye göre S4M4T hangi sözcüktür?', 'SİMİT', ['SIMIT', 'SEMET', 'SÜMÜT'], '4 sayısı İ harfini gösterir. S, M ve T değişmediğinden sözcük SİMİT\'tir.'),
  ('İngiliz alfabesinin kullanıldığı bir şifrede ARI sözcüğü BSJ, KOL sözcüğü de LPM olarak yazılmıştır. Bu şifrenin kuralı nedir?', 'Her harf alfabedeki bir sonraki harfle değiştirilir.', ['Her harf alfabedeki bir önceki harfle değiştirilir.', 'Sözcük tersten yazılıp harfler bir ileri kaydırılır.', 'Yalnızca ünlü harfler bir sonraki harfle değiştirilir.'], 'A→B, R→S, I→J ve K→L, O→P, L→M dönüşümleri her harfin bir ileri kaydığını gösterir; ünsüzler de değişmiştir.'),
  ('Her terimi bir harf ile o harfin alfabedeki sıra numarasından oluşan C3, F6, I9 dizisi aynı düzenle sürdürülürse dördüncü terim ne olur? (İngiliz alfabesi)', 'L12', ['K11', 'L11', 'M13'], 'Her terimdeki sayı, harfin alfabedeki sırasını gösterir ve harfler üçer atlayarak ilerler: C, F, I, L.'),
  ('Alfabenin sonundan başlayarak yazılan Z, Y, V, Ü, U harflerinin ardından aynı düzenle hangi harf gelmelidir? (29 harfli Türk alfabesi)', 'T', ['Ş', 'S', 'Ö'], 'Dizi, alfabenin son harflerinden başlayıp hiç harf atlamadan geriye doğru ilerlemektedir. U\'dan önce gelen harf T\'dir.'),
  ('Aşağıdaki sözcüklerden hangisi tersten okunduğunda aynı sözcük olarak kalmaz?', 'KALEM', ['KAYAK', 'KAZAK', 'KAPAK'], 'KAYAK, KAZAK ve KAPAK baştan ve sondan aynı okunur. KALEM tersten MELAK olur.'),
  ('Bir gazeteci belediye başkanına bütçedeki açığı soruyor. Başkan “Geçen yıl düzenlediğimiz konser ne kadar güzeldi, hatırlıyor musunuz?” yanıtını veriyor. Başkanın yanıtındaki hata hangisidir?', 'Konuyu başka bir yöne saptırmak', ['Az sayıda örnekten genelleme yapmak', 'Kanıtlanacak şeyi kanıt olarak kullanmak', 'Karşısındakinin kişiliğine saldırmak'], 'Soruya yanıt verilmemiş, dikkat ilgisiz ve olumlu bir konuya çekilmiştir.'),
  ('Saat 08.00\'de yola çıkan bir otobüsün yolculuğu, molalar hariç 3 saat 40 dakika sürmektedir. Otobüs yolda bir kez 25 dakika mola verirse varış saati kaç olur?', '12.05', ['11.40', '12.15', '11.55'], 'Yol süresi ile mola toplamı 4 saat 5 dakikadır. 08.00\'e eklenince 12.05 bulunur.'),
  ('Gün doğumu sırasında düz bir arazide yürüyen Kerem, uzun gölgesini görmek için dönüp arkasına bakması gerektiğini fark ediyor. Kerem hangi yöne doğru yürümektedir?', 'Doğuya', ['Batıya', 'Güneye', 'Kuzeye'], 'Doğan güneş gölgeyi batıya düşürür. Gölge Kerem\'in arkasında kaldığına göre Kerem güneşe, yani doğuya doğru yürümektedir.'),
  ('Ali, Veli\'nin babasıdır. Veli ile Sema evlidir ve Kaan bu çiftin oğludur. Ali, Kaan\'ın nesidir?', 'Dedesi', ['Amcası', 'Dayısı', 'Eniştesi'], 'Kaan\'ın babası Veli, Veli\'nin babası Ali\'dir. Babanın babası dededir.'),
  ('Elif\'in teyzesinin kızının annesi, Elif\'in nesi olur?', 'Annesinin kız kardeşi', ['Kendi annesi', 'Kuzeni', 'Babasının kız kardeşi'], 'Teyzenin kızının annesi teyzenin kendisidir. Uzun ifade aslında başlangıçtaki kişiye geri döner.'),
  ('Bir sabah eve dört şey geldi: süt, gazete, ekmek ve posta. Gazete sütten sonra ama ekmekten önce geldi. Ekmek en son gelen değildi. Posta en son geldi. Üçüncü sırada ne gelmiştir?', 'Ekmek', ['Gazete', 'Süt', 'Posta'], 'Posta dördüncüdür. Ekmek son olmadığına ve gazeteden sonra geldiğine göre üçüncüdür; gazete ikinci, süt birinci sıradadır.'),
  ('Dört kutu üst üste dizilmiştir. Yeşil kutu en üsttedir. Mavi kutu, sarı kutunun hemen üstündedir. Kırmızı kutu en altta değildir. En altta hangi kutu vardır?', 'Sarı', ['Kırmızı', 'Mavi', 'Yeşil'], 'Yeşil en üstte olduğundan alttaki üç yer kalır. Sarı ikinci sırada olsaydı mavi üçüncü, kırmızı en alta düşerdi; bu yasak olduğundan sarı en alttadır.'),
  ('Masada ters çevrilmiş üç bardak vardır ve top ortadaki bardağın altındadır. Önce soldaki ile ortadaki, sonra ortadaki ile sağdaki, en sonda da soldaki ile sağdaki bardak yer değiştiriyor. Top hangi bardağın altındadır?', 'Sağdaki bardağın', ['Soldaki bardağın', 'Ortadaki bardağın', 'Bilinemez'], 'İlk değişimle top sola geçer; ikinci değişim onu etkilemez; üçüncü değişimle soldan sağa geçer.'),
  ('“Kitap : kütüphane” ilişkisine göre “tablo : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Müze', ['Ressam', 'Fırça', 'Çerçeve'], 'Kitaplar kütüphanede sergilenip korunur; tablolar da müzede korunup sergilenir. Ressam yapan, fırça araç, çerçeve ise parçadır.'),
  ('Bir sınıftaki öğrencilerden en az biri İspanyolca bilmektedir. İspanyolca bilenlerin hepsi Fransızca da bilir. Buna göre hangisi kesinlikle doğrudur?', 'Sınıfta Fransızca bilen en az bir öğrenci vardır.', ['Sınıftaki her öğrenci Fransızca bilir.', 'Fransızca bilen her öğrenci İspanyolca da bilir.', 'Sınıfta İspanyolca bilmeyen öğrenci yoktur.'], 'İspanyolca bilen öğrenci aynı zamanda Fransızca bildiğinden sınıfta en az bir Fransızca bilen vardır.'),
  ('“Dün hem yağmur yağdı hem de rüzgâr esti.” cümlesinin yanlış olduğu öğrenilmiştir. Dün yağmurun yağdığı ise kesindir. Buna göre hangisi doğrudur?', 'Dün rüzgâr esmemiştir.', ['Dün rüzgâr da esmiştir.', 'Dün yağmur yağmamıştır.', 'Dün kar da yağmıştır.'], '“p ve q” yanlış, p doğru olduğuna göre q yanlış olmalıdır.'),
  ('Bir garson tek seferde en çok üç tabak taşıyabilmektedir. Mutfaktan masaya on tabak götürmesi gerekiyorsa en az kaç sefer yapmalıdır?', '4', ['3', '5', '10'], 'Üç seferde en çok dokuz tabak taşınabilir; onuncu tabak için dördüncü bir sefer gerekir.'),
  ('Bir kurye A, B, C ve D adreslerine birer kez uğrayacaktır. C\'ye B\'den önce gidecek, A\'yı en sona bırakacak, D\'ye de ilk olarak gitmeyecektir. Kurye ilk olarak hangi adrese gider?', 'C adresine', ['B adresine', 'D adresine', 'A adresine'], 'A sondadır. Kalan üç adreste D ilk olamaz, B de C\'den sonra gelmelidir; bu yüzden ilk adres yalnızca C olabilir.'),
  ('Bir fırına aynı anda en çok iki tepsi sığmaktadır. Her tepsideki kurabiyeler 15 dakikada pişiyor. Beş tepsi kurabiyenin hepsini pişirmek en az kaç dakika sürer?', '45 dakika', ['30 dakika', '40 dakika', '75 dakika'], 'İki, iki ve bir tepsi olmak üzere üç pişirme turu gerekir; 3 × 15 = 45 dakika.'),
  ('Bir kütüphanenin sesli çalışma odası yalnızca en az üç kişilik gruplarca ve önceden rezervasyon yapılarak kullanılabilir. Aşağıdakilerden hangisi odayı kullanabilir?', 'Rezervasyon yaptırmış dört kişilik bir grup', ['Rezervasyonu olmayan beş kişilik kalabalık bir grup', 'Rezervasyon yaptırmış ama yalnız gelen bir öğrenci', 'Rezervasyonu olan ama iki kişiden oluşan bir grup'], 'Odayı kullanmak için iki koşul birlikte aranır: en az üç kişi olmak ve rezervasyon yaptırmak. Yalnızca dört kişilik rezervasyonlu grup ikisini de sağlar.'),
  ('Bir sınıfta en yüksek sınav notu 95, en düşük not 40\'tır. Ali de bu sınıfta sınava girmiştir. Ali\'nin notu için hangisi kesinlikle doğrudur?', '40 ile 95 arasında ya da bunlardan birine eşittir.', ['Sınıf ortalamasının üzerindedir.', '40\'tan kesinlikle büyük, 95\'ten kesinlikle küçüktür.', 'Sınıfın tam ortalamasına eşittir.'], 'En yüksek ve en düşük not bütün notların sınırlarını belirler. Ali en yüksek ya da en düşük notu almış da olabilir, bu yüzden uçlar dışlanamaz.'),
  ('Selin okula zil çalmadan önce, Tuna zil çaldıktan sonra gelmiştir. Umut ise tam zil çaldığı anda okul kapısından girmiştir. Buna göre hangisi kesinlikle doğrudur?', 'Umut, Tuna\'dan önce gelmiştir.', ['Selin, Umut\'tan sonra okula gelmiştir.', 'Tuna, zil çalmadan önce okula gelmiştir.', 'Umut, üç arkadaşın en sonuncusudur.'], 'Zil anı bir ayraç gibidir: Selin ondan önce, Umut tam o anda, Tuna ondan sonra gelmiştir. Sıra Selin, Umut, Tuna\'dır.'),
  ('Ali, Banu ve Cem bir bulmacayı çözmeye aynı anda başlamıştır. Ali 10 dakikada bitirmiştir. Banu, Ali\'den 5 dakika uzun; Cem de Banu\'dan 3 dakika kısa sürede bitirmiştir. Bulmacayı ikinci bitiren kimdir?', 'Cem', ['Ali', 'Banu', 'Belirlenemez'], 'Süreler Ali 10, Banu 15, Cem 12 dakikadır. İkinci bitiren 12 dakikayla Cem\'dir.'),
  ('“Ayak : ayakkabı” ilişkisine göre “el : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Eldiven', ['Parmak', 'Bilezik', 'Kol'], 'Ayakkabı ayağı örtüp koruyan giysidir; eli örtüp koruyan giysi eldivendir. Parmak elin parçası, bilezik ise süs eşyasıdır.'),
  ('Bir rafta soldan sağa 1\'den 20\'ye kadar numaralı kitaplar dizilidir. 7 numaralı kitaptan 15 numaralı kitaba kadar, bu iki kitap da dâhil, kaç kitap vardır?', '9', ['8', '7', '10'], 'Uçlar dâhil sayıldığında kitap sayısı 15 − 7 + 1 = 9\'dur. Yalnızca fark alınırsa bir kitap eksik sayılır.'),
  ('Pazar günü ya sinemaya ya da tiyatroya gidilecektir. Tiyatronun biletleri tükenmişse tiyatroya gidilemeyecektir. Tiyatro biletlerinin tükendiği öğrenilmiştir. Pazar günü nereye gidilir?', 'Sinemaya gidilir.', ['Tiyatroya gidilir.', 'Hem sinemaya hem tiyatroya gidilir.', 'Hiçbir yere gidilmez.'], 'Biletler tükendiği için tiyatro seçeneği kalkar; iki seçenekten biri kesin olduğundan sinemaya gidilir.'),
  ('“Kimse her şeyi bilemez.” cümlesiyle aynı anlamı taşıyan cümle hangisidir?', 'Her şeyi bilen tek bir kişi yoktur.', ['Herkes en az bir şey bilir.', 'Bazı kişiler hiçbir şey bilmez, bazıları çok şey bilir.', 'Herkes her şeyi bilebilir.'], 'Cümle, her şeyi bilen bir kişinin var olmadığını söyler.'),
  ('İki kız kardeşten biri Kemal\'le, diğeri Tarık\'la evlidir. Kemal ile Tarık birbirlerinin nesi olur?', 'Bacanak', ['Kayınbirader', 'Elti', 'Enişte'], 'Kız kardeşlerle evli iki erkek birbirinin bacanağıdır. Erkek kardeşlerle evli iki kadın ise birbirinin eltisidir.'),
  ('Bir uçak bir havalimanından kalkıp önce 300 km kuzeye, ardından 400 km batıya uçmuştur. Uçak, kalktığı havalimanına göre hangi yöndedir?', 'Kuzeybatısında', ['Kuzeydoğusunda', 'Güneybatısında', 'Başlangıç noktasının tam batısında'], 'Kuzeye ve batıya gidildiği için uçak iki yönün arasında, yani kuzeybatıda kalır.'),
  ('A olayı B\'den iki gün önce, C olayı B\'den bir gün sonra, D olayı da A\'dan bir gün sonra gerçekleşmiştir. Bu olaylardan en son hangisi olmuştur?', 'C', ['B', 'D', 'A'], 'A\'yı 0. gün sayarsak D 1., B 2., C 3. gündedir. En son olan C\'dir.'),
  ('Bir öğrenci aynı topu farklı yüksekliklerden bırakıp topun her seferinde ne kadar yükseğe sektiğini ölçüyor. Bu deneyde bağımlı değişken hangisidir?', 'Topun sekme yüksekliği', ['Topun bırakıldığı yükseklik', 'Topun yapıldığı malzeme', 'Deneyin yapıldığı oda'], 'Bağımlı değişken ölçülen sonuçtur. Bırakılma yüksekliği değiştirilen (bağımsız) değişkendir; top ve oda sabit tutulur.'),
  ('Bir vazoyu Ali, Banu ve Cem\'den tam iki kişi birlikte kırmıştır. Ali “Banu suçsuzdur.”, Banu “Cem suçludur.”, Cem “Ali suçludur.” diyor. Üç sözün üçü de doğruysa vazoyu kimler kırmıştır?', 'Ali ile Cem', ['Ali ile Banu', 'Banu ile Cem', 'Belirlenemez'], 'Banu suçsuz olduğuna göre suçlu ikili Ali ile Cem\'dir; bu durumda Banu ile Cem\'in sözleri de doğrudur.'),
  ('Bir mağazanın iade kuralı şöyledir: Fişi olan müşteri ürünü 30 gün içinde iade edebilir. Fişi olmayan müşteri ise yalnızca 15 gün içinde ve yalnızca değişim yapabilir. Fişi olmayan bir müşteri ürünü 10 gün sonra mağazaya getirmiştir. Müşteri ne yapabilir?', 'Ürünü yalnızca başka bir ürünle değiştirebilir.', ['Ürünü iade edip parasını geri alabilir.', 'Ürünü ne iade edebilir ne de değiştirebilir.', 'Ürünü iade edebilir ama değiştiremez.'], 'Fiş olmadığı için iade hakkı yoktur. 10 gün, 15 günlük değişim süresinin içinde kaldığından değişim yapılabilir.'),
  ('Bir spor salonuna 16 yaşından küçükler yalnızca hafta sonları ve bir ebeveynle girebilmektedir. 15 yaşındaki Can bir çarşamba günü babasıyla salona gelmiştir. Can için hangisi doğrudur?', 'Can o gün salona giremez.', ['Babası yanında olduğu için Can salona girebilir.', 'Can yalnız gelseydi o gün salona girebilirdi.', 'Can\'ın girebilmesi için annesinin de gelmesi gerekir.'], 'İki koşul birlikte aranır: hafta sonu olmak ve ebeveynle gelmek. Çarşamba hafta sonu olmadığından Can giremez.'),
  ('Bir sitenin şifre kuralı şöyledir: En az 8 karakter olmalı, en az bir rakam ve en az bir büyük harf içermelidir. Aşağıdaki şifrelerden hangisi bu kurala uyar?', 'Deniz2024', ['kaya2024ab', 'Deniz24', 'DenizKaya'], '“kaya2024ab” büyük harf, “Deniz24” yeterli uzunluk, “DenizKaya” ise rakam içermez. “Deniz2024” dokuz karakterlidir, rakam ve büyük harf içerir.'),
  ('Bir havayolu şirketinde 20 kg\'ı aşan bagajlar için ek ücret alınır; 32 kg\'ı aşan bagajlar ise hiç kabul edilmez. 25 kg\'lık bir bagaj için hangisi doğrudur?', 'Ek ücret ödenerek kabul edilir.', ['Ücretsiz olarak kabul edilir.', 'Hiçbir koşulda kabul edilmez.', 'Yalnızca yarısı uçağa alınır.'], '25 kg, 20 kg sınırını aşar ama 32 kg sınırının altındadır; bu yüzden ek ücretle kabul edilir.'),
  ('Bir yarışmaya dört kişi katılmış ve altın, gümüş, bronz olmak üzere üç madalya dağıtılmıştır. Her yarışmacı en çok bir madalya alabildiğine göre hangisi kesinlikle doğrudur?', 'Yarışmacılardan biri madalya alamamıştır.', ['Her yarışmacı en az bir madalya almıştır.', 'İki yarışmacı aynı madalyayı paylaşmıştır.', 'Madalyaların biri kimseye verilmemiştir.'], 'Üç madalya en çok üç kişiye gidebilir. Dört yarışmacıdan en az biri madalyasız kalır.'),
  ('Aşağıdakilerden hangisi bir yorum değil, doğrudan bir gözlem cümlesidir?', 'Termometre 23 °C\'yi gösteriyor.', ['Bugün hava gerçekten çok güzel.', 'Yarın büyük olasılıkla yağmur yağacak.', 'Bu sıcaklık bitkiler için çok uygundur.'], 'Termometrenin gösterdiği değer doğrudan okunabilir. Diğer cümleler beğeni, tahmin ya da değerlendirme içerir.'),
  ('Bir bilim insanının dikkatle yaptığı deneyler, öne sürdüğü hipotezi desteklememiştir. Bu durumda yapması gereken en uygun şey hangisidir?', 'Hipotezi gözden geçirip değiştirmek', ['Verileri hipoteze uyacak biçimde düzeltmek', 'Deney sonuçlarını hiç yayımlamamak', 'Hipotezi kanıtlanmış gibi sunmak'], 'Bilimsel yöntemde hipotez kanıtlara göre düzeltilir; kanıtlar hipoteze göre değiştirilmez.'),
  ('“Bu hatta bilet fiyatları arttı. Ayrıca yolculuk süresi de uzadı. O hâlde bu hatta yolcu sayısı azalacaktır.” akıl yürütmesinin sonucu hangisidir?', 'Hattaki yolcu sayısının azalacağı', ['Bilet fiyatlarının artmış olduğu', 'Yolculuk süresinin uzamış olduğu', 'Hattın yakında kapatılacağı'], '“O hâlde” ifadesinden sonra gelen yargı sonuçtur; fiyat artışı ve süre uzaması ise gerekçelerdir.'),
  ('Bir yemek tarifinde soğan kavrulmadan et eklenmez, et eklenmeden su konmaz, baharat da su konduktan sonra eklenir. Dört adımdan üçüncüsü hangisidir?', 'Su eklemek', ['Et eklemek', 'Baharat eklemek', 'Soğanı kavurmak'], 'Sıra soğan, et, su ve baharat biçimindedir; üçüncü adım su eklemektir.'),
  ('Beş öğrenci sınavı farklı zamanlarda bitirmiştir. Ali, Banu\'dan önce; Cem, Ali\'den önce; Deniz, Banu\'dan sonra; Ece de Cem\'den önce bitirmiştir. Sınavı üçüncü bitiren kimdir?', 'Ali', ['Cem', 'Banu', 'Ece'], 'Sıra Ece, Cem, Ali, Banu, Deniz biçiminde tek olarak belirlenir.'),
  ('Bir konser 20.00\'de başlayacaktır. Ayşe konser alanında başlangıçtan 30 dakika önce olmak istiyor. Yol 50 dakika, hazırlanması da 40 dakika sürüyor. Ayşe hazırlanmaya en geç saat kaçta başlamalıdır?', '18.00', ['17.20', '18.20', '17.40'], 'Toplam 30 + 50 + 40 = 120 dakika, yani 2 saat gerekir. 20.00\'den iki saat önce 18.00\'dir.'),
  ('“Pusula : yön” ilişkisine göre “saat : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Zaman', ['Akrep', 'Duvar', 'Pil'], 'Pusula yönü, saat de zamanı göstermeye yarayan araçtır. Akrep saatin parçası, pil ise çalışma kaynağıdır.'),
  ('“Yazar : kitap” ilişkisine göre “besteci : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Beste', ['Sahne', 'Piyano', 'Dinleyici'], 'Yazar kitabı, besteci de besteyi ortaya koyar. Piyano araç, sahne mekân, dinleyici ise alıcıdır.'),
  ('Üst üste dizili üç çekmeceden birinde anahtar, birinde kalem vardır, biri ise boştur. Anahtar ne birinci (üst) ne de üçüncü (alt) çekmecededir. Boş çekmece ortada değildir. Kalem üçüncü çekmecede değildir. Boş olan hangi çekmecedir?', 'En alttaki çekmece', ['En üstteki çekmece', 'Ortadaki çekmece', 'Üstteki ya da ortadaki'], 'Anahtar ortadaki çekmecede olmak zorundadır. Kalem en altta olamayacağı için en üstte, boş çekmece de en alttadır.'),
  ('İki saatten biri 2 saat ileri, öteki 1 saat geridir. İleri olan saat 15.00\'i gösterdiğinde gerçek saat kaçtır?', '13.00', ['14.00', '12.00', '16.00'], 'İleri olan saat gerçek saatten 2 saat fazlasını gösterir; 15.00 − 2 saat = 13.00.'),
  ('Bir tren A istasyonundan 09.15\'te kalkıyor ve 1 saat 50 dakikada B istasyonuna varıyor. B\'de 10 dakika bekledikten sonra 45 dakikada C istasyonuna ulaşıyor. Tren C istasyonuna saat kaçta varır?', '12.00', ['11.50', '11.40', '12.10'], '09.15 + 1 saat 50 dakika = 11.05; 10 dakika bekleme ile 11.15; 45 dakika yolla 12.00 olur.'),
  ('Ayşe ile Fatma\'nın yaşları toplamı 20\'dir ve Ayşe, Fatma\'dan büyüktür. Buna göre hangisi kesinlikle doğrudur?', 'Ayşe 10 yaşından büyüktür.', ['Fatma tam 8 yaşındadır.', 'Ayşe, Fatma\'nın iki katı yaşındadır.', 'Fatma 10 yaşından büyüktür.'], 'Yaşlar eşit olsaydı ikisi de 10 olurdu. Ayşe daha büyük olduğuna göre 10\'un üstünde, Fatma ise altındadır.'),
  ('40 kişilik koltuğu olan bir otobüste 43 yolcu yolculuk etmektedir ve her koltuğa en çok bir kişi oturabilir. Buna göre hangisi kesinlikle doğrudur?', 'En az üç yolcu ayakta yolculuk etmektedir.', ['Otobüsteki bütün koltuklar doludur.', 'Tam olarak üç koltuk boş kalmıştır.', 'Yolculardan en az biri şoför koltuğundadır.'], 'Koltuklara en çok 40 kişi oturabilir; geriye en az 3 yolcu kalır. Boş koltuk olup olmadığı ise bilinemez.'),
  ('Toplantı ya pazartesi ya da salı yapılacaktır. Toplantı pazartesi yapılırsa Ali katılamayacaktır. Ali toplantıya katılmıştır. Buna göre toplantı hangi gün yapılmıştır?', 'Salı', ['Pazartesi', 'Çarşamba', 'Belirlenemez'], 'Ali katıldığına göre toplantı pazartesi yapılmamıştır. Geriye yalnızca salı kalır.'),
  ('Bütün kırmızı kalemler mavi kutudadır. Mavi kutudaki bütün kalemler yenidir. Buna göre hangisi kesinlikle doğrudur?', 'Bütün kırmızı kalemler yenidir.', ['Mavi kutudaki her kalem kırmızıdır.', 'Yeni kalemlerin tamamı mavi kutudadır.', 'Kırmızı olmayan kalemler eskidir.'], 'Kırmızı kalemler mavi kutudakiler kümesinde, bu küme de yeni kalemler kümesindedir; dolayısıyla kırmızı kalemler yenidir.'),
  ('Bir reklamda “Bu alarm sistemini hemen almazsanız eviniz her an soyulabilir!” deniyor. Bu reklamda hangi akıl yürütme hatası vardır?', 'Korkuya başvurma', ['Geleneğe başvurma', 'Bölme hatası', 'Döngüsel akıl yürütme'], 'Ürünün yararına dair kanıt sunulmamış, dinleyicinin korkusu harekete geçirilerek karar vermesi istenmiştir.'),
  ('Bir deneyde kontrol grubu için aşağıdakilerden hangisi doğrudur?', 'Deney grubuyla aynı koşullarda tutulur ama incelenen etkene maruz kalmaz.', ['İncelenen etkenin en yüksek dozuna maruz bırakılan gruptur.', 'Deneyi yöneten araştırmacılardan oluşan gruptur.', 'Deney bittikten sonra sonuçları denetleyen bağımsız kuruldur.'], 'Kontrol grubu, etkenin etkisini görebilmek için karşılaştırma ölçütü olarak kullanılır; tek fark incelenen etkenin bulunmamasıdır.'),
  ('Bir yüzme havuzunun kuralları şöyledir: Duş almadan havuza girilmez. Bone takmayan havuza giremez. 10 yaşından küçükler yanlarında bir yetişkin olmadan havuza giremez. 12 yaşındaki Arda duş almış, bonesini takmış ve havuza yalnız gelmiştir. Arda için hangisi doğrudur?', 'Arda havuza girebilir.', ['Arda\'nın havuza girebilmesi için yanında bir yetişkin gerekir.', 'Arda bone taktığı hâlde duş almadığı için giremez.', 'Arda yalnız geldiği için havuza kesinlikle giremez.'], 'Yetişkin koşulu yalnızca 10 yaşından küçükler içindir. Arda diğer iki koşulu da sağladığından havuza girebilir.'),
  ('Bir sınav salonuna 09.00\'dan sonra kimse alınmaz; sınav 09.30\'da başlar ve 10.00\'dan önce salondan çıkılamaz. Ali sınav günü salonun kapısına 09.10\'da gelmiştir. Ali için hangisi doğrudur?', 'Ali sınava giremez.', ['Ali sınava girer ama 10.00\'dan önce çıkamaz.', 'Ali sınav başlamadan önce geldiği için girebilir.', 'Ali yalnızca 09.30\'dan sonra içeri alınabilir.'], 'Giriş sınırı sınavın başlama saatine değil 09.00\'a göredir. 09.10\'da gelen Ali bu sınırı geçmiştir.'),
  ('Bir sinemada öğrencilere %30, 65 yaş üstündekilere %50 indirim uygulanır. Birden çok indirim hakkı olan kişi yalnızca en yüksek indirimi kullanabilir. 67 yaşındaki ve üniversitede öğrenci olan Nazım Bey kaç indirim alır?', '%50', ['%30', '%80', '%65'], 'İki indirim toplanmaz; yalnızca yüksek olan uygulanır. Nazım Bey 65 yaş üstü olduğundan %50 indirim alır.'),
  ('Sinan, Tolga\'dan önce mezun olmuştur. Tolga, Umut\'tan sonra mezun olmuştur. Umut ise Sinan\'dan önce mezun olmuştur. Üçü arasında ilk mezun olan kimdir?', 'Umut', ['Sinan', 'Tolga', 'Belirlenemez'], 'Umut, Sinan\'dan; Sinan da Tolga\'dan önce mezun olduğuna göre sıra Umut, Sinan, Tolga\'dır.'),
  ('Saat 14.00\'te başlayan bir filmin kendisi 2 saat 15 dakika sürmektedir. Filmin ortasında, bu süreye dâhil olmayan 15 dakikalık bir ara verilmektedir. Film saat kaçta biter?', '16.30', ['16.15', '16.45', '16.00'], 'Film süresi ile ara birlikte 2 saat 30 dakikadır. 14.00\'e eklenince 16.30 bulunur.'),
  ('Bir bahçe lambası yalnızca hava karardığında ve aynı anda hareket algılandığında yanmaktadır. Lambanın şu anda yandığı görülmüştür. Buna göre hangisi kesinlikle doğrudur?', 'Hava kararmıştır ve hareket algılanmıştır.', ['Hava kararmış ama hareket algılanmamıştır.', 'Hareket algılanmış ama hava aydınlıktır.', 'Lamba gün boyu açık bırakılmıştır.'], '“Yalnızca … ve … olduğunda yanar” ifadesi, lamba yanıyorsa iki koşulun da gerçekleştiğini gösterir.'),
  ('“Gemi : liman” ilişkisine göre “uçak : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Havalimanı', ['Pilot', 'Kanat', 'Bulut'], 'Gemiler limana yanaşıp orada bekler; uçaklar da havalimanına iner ve orada bekler. Pilot kullanıcı, kanat ise parçadır.'),
  ('“Mürekkep : dolma kalem” ilişkisine göre “? : otomobil” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Yakıt', ['Direksiyon', 'Sürücü', 'Otoyol'], 'Mürekkep dolma kalemin çalışması için tükettiği maddedir; otomobilin tükettiği madde de yakıttır.'),
  ('Bir kuyrukta Mert\'in önünde 5, arkasında 7 kişi vardır. Nil, Mert\'ten üç kişi geridedir. Nil\'in arkasında kaç kişi vardır?', '4', ['3', '5', '2'], 'Mert\'in arkasındaki 7 kişiden ilk üçü sayılınca Nil\'e ulaşılır; Nil\'in arkasında 7 − 3 = 4 kişi kalır.'),
  ('Kuzeyin üst kenarda olduğu bir şehir haritası masada 180° döndürülmüştür. Haritanın şimdi üst kenarı gerçekte hangi yönü göstermektedir?', 'Güneyi', ['Kuzeyi', 'Doğuyu', 'Batıyı'], 'Harita yarım tur döndürülünce eski alt kenar üste gelir. Eski alt kenar güneyi gösterdiğinden üst kenar artık güneydir.'),
  ('“Öğretmen : okul” ilişkisine göre “hemşire : ?” ikilisinde soru işaretinin yerine hangisi gelmelidir?', 'Hastane', ['Hasta', 'İlaç', 'Doktor'], 'Öğretmen okulda, hemşire hastanede çalışır. Hasta hizmet alan kişi, ilaç ise kullanılan maddedir.'),
  ('Bir kütüphanede kitaplar 14 gün süreyle ödünç verilir ve bir kez 7 gün uzatılabilir; ancak başka biri tarafından ayrılmış (rezerve edilmiş) kitaplar uzatılamaz. Ece\'nin elindeki kitap başka bir okur tarafından ayrılmıştır ve bugün 14. gündür. Ece ne yapmalıdır?', 'Kitabı bugün teslim etmelidir.', ['Kitabı 7 gün daha uzatabilir.', 'Kitabı iki kez uzatabilir.', 'Kitabı 21. güne kadar tutabilir.'], 'Uzatma hakkı rezerveli kitaplarda kullanılamaz. Süre bugün dolduğuna göre kitap teslim edilmelidir.'),
  ('Bir ligde puan eşitliğinde önce averaja, averaj da eşitse iki takım arasındaki maçların sonucuna bakılır. A ve B takımları 20\'şer puanla ve +5 averajla eşit bitirmiştir; aralarındaki maçı A kazanmıştır. Sıralama için hangisi doğrudur?', 'A takımı B\'nin üstünde yer alır.', ['B takımı A\'nın üstünde yer alır.', 'İki takım aynı sırayı paylaşır.', 'Sıralama kura çekilerek belirlenir.'], 'Puan ve averaj eşit olduğundan üçüncü ölçüte geçilir; ikili maçı kazanan A üstte yer alır.'),
  ('Bir öğrenci “Bu sınavdan 90 alırsam ya bisiklet ya da telefon alacağım.” demiştir. Öğrenci 90 almış ve telefon almamıştır. Sözünü tuttuğu biliniyorsa hangisi kesindir?', 'Bisiklet almıştır.', ['Hiçbir şey satın almamıştır.', 'Telefonu daha sonra alacaktır.', '90\'dan düşük not almıştır.'], 'Koşul gerçekleştiği için iki seçenekten biri yapılmalıdır. Telefon alınmadığına göre bisiklet alınmıştır.'),
  ('12 basamaklı bir merdiveni çıkan biri her adımda ya bir ya da iki basamak çıkabilmektedir. Merdivenin tepesine en az kaç adımda ulaşılır?', '6', ['12', '4', '7'], 'Her adımda en çok iki basamak çıkılabildiği için 12 basamak en az 6 adımda tamamlanır.'),
  ('Bir şifrede sözcüğün harf sayısı başa yazılır, ardından sözcük tersten yazılır; örneğin GÜL sözcüğü 3LÜG olur. Bu kurala göre NAR sözcüğü nasıl yazılır?', '3RAN', ['3NAR', 'RAN3', '2RAN'], 'NAR üç harflidir; başa 3 yazılır ve sözcük tersten RAN olarak eklenir.'),
  ('Pazartesiden başlayarak haftanın günlerinin baş harfleri yazılıyor: P, S, Ç, P, C, … Dizide bir sonraki harf hangisidir?', 'C', ['P', 'S', 'Ç'], 'Pazartesi, salı, çarşamba, perşembe, cuma günlerinden sonra cumartesi gelir; baş harfi C\'dir.'),
  ('Bir kutu oyununda mavi karta basan oyuncu bir kare ileri, kırmızı karta basan iki kare geri gider. Beşinci karede duran bir oyuncu sırasıyla mavi, kırmızı ve yine mavi karta basmıştır. Oyuncu şimdi kaçıncı karededir?', '5. karede', ['6. karede', '4. karede', '7. karede'], 'Mavi ile 6\'ya, kırmızı ile 4\'e, ikinci mavi ile yeniden 5\'e gelir; ileri ve geri hareketler birbirini dengeler.'),
  ('Bir mağazada taksitli ödeme yalnızca kredi kartıyla yapılan alışverişlerde mümkündür. Zafer bu mağazadan taksitle bir buzdolabı almıştır. Buna göre hangisi kesinlikle doğrudur?', 'Zafer ödemeyi kredi kartıyla yapmıştır.', ['Zafer ödemeyi nakit olarak yapmıştır.', 'Kartla ödeyen herkes taksit kullanır.', 'Zafer indirimli bir ürün satın almıştır.'], 'Taksit yalnızca kartla mümkün olduğundan taksit kullanan herkes kartla ödemiştir. Kartla ödeyen herkesin taksit kullandığı ise söylenemez.'),
  ('Ayşe bir sabah dört yere uğramıştır. Ekmeği almadan önce bankaya gitmiş, bankadan önce eczaneye uğramıştır. Postaneye ise ekmeği aldıktan sonra gitmiştir. Ayşe\'nin ikinci olarak uğradığı yer neresidir?', 'Banka', ['Eczane', 'Fırın', 'Postane'], 'Sıra eczane, banka, fırın (ekmek) ve postane biçimindedir. İkinci durak bankadır.'),
  ('Bir rüzgâr gülünün oku güneybatıyı göstermektedir. Ok tam ters yöne dönerse hangi yönü gösterir?', 'Kuzeydoğuyu', ['Kuzeybatıyı', 'Güneydoğuyu', 'Doğuyu'], 'Bir yönün tam tersi 180° ötesindedir. Güneybatının karşıtı kuzeydoğudur.'),
  ('Beş öğrencinin her biri 1, 2, 3 ve 4 sayılarından birini seçiyor. Buna göre hangisi kesinlikle doğrudur?', 'En az iki öğrenci aynı sayıyı seçmiştir.', ['Her sayı en az bir öğrenci tarafından seçilmiştir.', 'Tam olarak iki öğrenci 1 sayısını seçmiştir.', 'Üç öğrenci aynı sayıyı seçmiş olmalıdır.'], 'Dört seçenek beş kişiye yetmez; en az bir sayı iki kişi tarafından seçilir. Seçilmeyen sayı olup olmadığı ise bilinemez.'),
];
